// Junta el apartado con la factura. La liga es la que el agente manda por WhatsApp.
// /invoices/ NO devuelve la liga; se arma a mano. Formato confirmado el 25 sep.
const apartado = $('Arrancar reloj de 24 h').first().json;
const factura = $('GHL · crear factura').first().json;
const invoice_id = factura._id || factura.id;
return [{ json: { ...apartado, invoice_id,
  liga_pago: `${$('Config').first().json.GHL_INVOICE_URL_BASE}/invoice/${invoice_id}` } }];

// El apartado va a la oportunidad del lead (etapa 1 o 2) si hay una abierta.
// Si no, se crea una: nunca se reusa la de otro pedido que ya va más adelante.
const c = $('Config').first().json;
const tempranas = [c.GHL_STAGE_LEAD, c.GHL_STAGE_CONVERSACION];
const ops = $('GHL · pedidos del contacto').first().json.opportunities || [];
const o = ops.find(x => tempranas.includes(x.pipelineStageId));
return [{ json: { opportunityId: o ? o.id : '' } }];
